#!/usr/bin/env python3
"""Packs the cat recordings in js/sound/*.mp3 into js/sound/samples.js.

The game is opened by double-clicking index.html, and browsers won't let a page loaded
from disk fetch other files. A script tag works, so the recordings ride along inside one.
Run this again whenever you replace an mp3:  python3 tools/embed-sounds.py
"""
import base64
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
files = {
    'meow': 'cat-meow-default.mp3',
    'hiss': 'cat-meow-hiss.mp3',
    'purr': 'cat-meow-purring.mp3',
}
lines = [
    '// Generated by tools/embed-sounds.py from the mp3 files next to this one. Do not edit by hand.',
    '(function (G) {',
    "  'use strict';",
    '  G.SoundData = {',
]
for key, name in files.items():
    b64 = base64.b64encode((root / 'js' / 'sound' / name).read_bytes()).decode()
    lines.append(f"    {key}: 'data:audio/mpeg;base64,{b64}',")
lines += ['  };', "})(globalThis.CatGame = globalThis.CatGame || {});", '']
out = root / 'js' / 'sound' / 'samples.js'
out.write_text('\n'.join(lines))
print(f'wrote {out.relative_to(root)} ({out.stat().st_size // 1024} KB)')
